def add(table, row, col, rule): V.append({"table": table, "row": row, "column": col, "rule": rule})

def is_date(s):
    try:
        datetime.strptime(s, "%Y-%m-%d"); return True
    except ValueError: return False
def is_num(s):
    try: float(s); return True
    except ValueError: return False

EMAIL = re.compile(r"^[^@]+@[^@.]+\.[a-z]{2,}$")

# customers
seen = set()
for i, r in enumerate(customers, 1):
    for col in ("id", "email", "signup_date", "tier"):
        if not r[col].strip(): add("customers", i, col, "not_null")
    if r["id"] in seen: add("customers", i, "id", "unique")
    seen.add(r["id"])
    if not EMAIL.match(r["email"]): add("customers", i, "email", "email")
    if not is_date(r["signup_date"]): add("customers", i, "signup_date", "date")
    if r["tier"] not in ("free", "pro", "enterprise"): add("customers", i, "tier", "enum")

# orders
cust_ids = {r["id"] for r in customers}
seen = set()
order_ok = {}  # id -> total valid
for i, r in enumerate(orders, 1):
    for col in ("id", "customer_id", "order_date", "status", "total"):
        if not r[col].strip(): add("orders", i, col, "not_null")
    if r["id"] in seen: add("orders", i, "id", "unique")
    seen.add(r["id"])
    if r["customer_id"] not in cust_ids: add("orders", i, "customer_id", "foreign_key")
    if not is_date(r["order_date"]): add("orders", i, "order_date", "date")
    if r["status"] not in ("placed", "paid", "shipped", "cancelled"): add("orders", i, "status", "enum")
    total_ok = is_num(r["total"]) and float(r["total"]) >= 0
    if not total_ok: add("orders", i, "total", "range")
    order_ok[r["id"]] = total_ok and is_num(r["total"]) and float(r["total"])

# order_items
prod_skus = {r["sku"] for r in products}
for i, r in enumerate(items, 1):
    for col in ("order_id", "sku", "qty", "price"):
        if not r[col].strip(): add("order_items", i, col, "not_null")
    if r["order_id"] not in {o["id"] for o in orders}: add("order_items", i, "order_id", "foreign_key")
    if r["sku"] not in prod_skus: add("order_items", i, "sku", "foreign_key")
    qty_ok = re.match(r"^\d+$", r["qty"]) and int(r["qty"]) >= 1
    if not qty_ok: add("order_items", i, "qty", "range")
    if not (is_num(r["price"]) and float(r["price"]) >= 0): add("order_items", i, "price", "range")

# products
seen = set()
for i, r in enumerate(products, 1):
    for col in ("sku", "name", "price", "category"):
        if not r[col].strip(): add("products", i, col, "not_null")
    if r["sku"] in seen: add("products", i, "sku", "unique")
    seen.add(r["sku"])
    if not (is_num(r["price"]) and float(r["price"]) > 0): add("products", i, "price", "range")

# refunds
seen = set()
for i, r in enumerate(refunds, 1):
    for col in ("id", "order_id", "amount", "date"):
        if not r[col].strip(): add("refunds", i, col, "not_null")
    if r["id"] in seen: add("refunds", i, "id", "unique")
    seen.add(r["id"])
    if r["order_id"] not in {o["id"] for o in orders}: add("refunds", i, "order_id", "foreign_key")
    amt_ok = is_num(r["amount"]) and float(r["amount"]) > 0
    if not amt_ok: add("refunds", i, "amount", "range")
    # refund_le_total: only when amount passes range and order exists with valid total
    o = next((o for o in orders if o["id"] == r["order_id"]), None)
    if amt_ok and o and order_ok.get(o["id"]) is not None and float(r["amount"]) > order_ok[o["id"]]:
        add("refunds", i, "amount", "refund_le_total")

# shipments
order_dates = {o["id"]: o["order_date"] for o in orders}
for i, r in enumerate(shipments, 1):
    for col in ("order_id", "carrier", "shipped_date"):
        if not r[col].strip(): add("shipments", i, col, "not_null")
    o = next((o for o in orders if o["id"] == r["order_id"]), None)
    if not o: add("shipments", i, "order_id", "foreign_key")
    if r["carrier"] not in ("ups", "dhl", "fedex"): add("shipments", i, "carrier", "enum")
    sd_ok = is_date(r["shipped_date"])
    if not sd_ok: add("shipments", i, "shipped_date", "date")
    # ship_after_order: only when shipped_date valid, order exists, its order_date valid
    if sd_ok and o and is_date(o["order_date"]) and r["shipped_date"] < o["order_date"]:
        add("shipments", i, "shipped_date", "ship_after_order")

V.sort(key=lambda v: (v["table"], v["row"], v["column"], v["rule"]))
os.makedirs("/app/out", exist_ok=True)
with open("/app/out/dq-report.json", "w") as f:
    json.dump(V, f, indent=2)
print(json.dumps(V, indent=2))
print(f"\nTotal: {len(V)}")
